def firstBreakingEdge(n, edges):
    parent = list(range(n))
    par = [0] * n      # colour difference between a node and its parent
    size = [1] * n

    def find(x):
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        root = x
        acc = 0
        for node in reversed(path):
            acc ^= par[node]
            par[node] = acc
            parent[node] = root
        return root

    for i, (a, b) in enumerate(edges):
        ra, rb = find(a), find(b)
        pa, pb = par[a], par[b]    # a and b are now attached to their roots (or are roots with difference 0)
        if ra == rb:
            if pa == pb:
                return i
        else:
            if size[ra] > size[rb]:
                ra, rb = rb, ra
            parent[ra] = rb
            par[ra] = pa ^ pb ^ 1
            size[rb] += size[ra]
    return -1
